// spec: specs/guides-videos.md (1.5) · кейс: .qa/tests/guides-videos/GUIDES-05.md
// seed: tests/seed.admin.spec.ts (admin, с #359741; было: гость) · прод, только чтение. Chromium: webkitAudioDecodedByteCount > 0 — звук реально декодируется.
// Декодирован ≠ слышна речь — речь проверяется вручную (GUIDES-07).
import { test, expect } from '@playwright/test';
import { prepareReadOnly, GUIDES, LOAD, openGuides, videoOf, mp4Response, startDesktop, expectPlaying, videoState, stop } from './guides.helpers';

// #359741: /guides видит только админ (гость и user уходят на /) — сессия admin, файл сессии не перезаписывается.
test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test.describe('Видео-инструкции /guides — звук декодируется', () => {
  for (const g of GUIDES) {
    test(`${g.id}: при воспроизведении Chromium декодирует звук (webkitAudioDecodedByteCount > 0) #8790d6 @desktop @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openGuides(page);
      const video = videoOf(page, g);

      const resp = mp4Response(page, g);
      await startDesktop(page, video);
      await resp;
      await expectPlaying(video, 2, g.id);
      await expect
        .poll(() => video.evaluate((v) => (v as HTMLVideoElement & { webkitAudioDecodedByteCount?: number }).webkitAudioDecodedByteCount ?? -1),
          { message: `${g.id}: webkitAudioDecodedByteCount > 0 (-1 — API нет)`, ...LOAD })
        .toBeGreaterThan(0);
      expect((await videoState(video)).muted, `${g.id}: звук не выключен (muted)`).toBe(false);
      await stop(video);
    });
  }
});
